391	// Invite returns one of an organization's invites.
392	func (s *Store) Invite(orgID, id string) (Invite, bool) {
393		s.mu.Lock()
394		defer s.mu.Unlock()
395		inv, ok := s.invites[id]
396		if !ok || inv.OrgID != orgID {
397			return Invite{}, false
398		}
399		return inv, true
400	}
