package api

import (
	"encoding/json"
	"net/http"
	"reflect"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

// auditSecretFields are never logged: an API key's token, a webhook endpoint's secret and an invite's token.
var auditSecretFields = map[string]bool{"token": true, "secret": true}

// audit records a change that a successful request made. Failed requests record nothing, so callers call it only once the
// change is made and the answer is a success.
func (s *Server) audit(r *http.Request, p auth.Principal, action, targetType, targetID string) {
	s.appendAudit(r, p, action, targetType, targetID, nil)
}

// auditUpdate records an update: action on target, with the fields whose value differs between before and after.
func (s *Server) auditUpdate(r *http.Request, p auth.Principal, action, targetType, targetID string, before, after any) {
	changes := changedFields(before, after)
	s.appendAudit(r, p, action, targetType, targetID, &changes)
}

func (s *Server) appendAudit(r *http.Request, p auth.Principal, action, targetType, targetID string, changes *map[string]store.AuditChange) {
	s.store.AppendAudit(store.AuditEntry{
		OrgID:     p.OrgID,
		Action:    action,
		Actor:     store.AuditActor{Type: "api_key", ID: p.KeyID, UserID: p.UserID},
		Target:    store.AuditTarget{Type: targetType, ID: targetID},
		RequestID: RequestID(r.Context()),
		Changes:   changes,
	}, s.clock.Now())
}

// changedFields returns the JSON fields of after whose value differs from before's, with both values. The values are
// compared as JSON, so the field names are the ones the API uses. The types passed here always marshal.
func changedFields(before, after any) map[string]store.AuditChange {
	b, a := jsonFields(before), jsonFields(after)
	names := map[string]bool{}
	for k := range b {
		names[k] = true
	}
	for k := range a {
		names[k] = true
	}
	out := map[string]store.AuditChange{}
	for k := range names {
		if auditSecretFields[k] || reflect.DeepEqual(b[k], a[k]) {
			continue
		}
		out[k] = store.AuditChange{From: b[k], To: a[k]}
	}
	return out
}

func jsonFields(v any) map[string]any {
	var m map[string]any
	b, _ := json.Marshal(v)
	_ = json.Unmarshal(b, &m)
	return m
}

// auditView is an audit entry as the API shows it.
type auditView struct {
	ID        string                        `json:"id"`
	Action    string                        `json:"action"`
	Actor     store.AuditActor              `json:"actor"`
	Target    store.AuditTarget             `json:"target"`
	RequestID string                        `json:"request_id"`
	At        time.Time                     `json:"at"`
	Changes   *map[string]store.AuditChange `json:"changes,omitempty"`
}

func auditViewKey(v auditView) cursor { return cursor{T: v.At, ID: v.ID} }

// listAuditEvents lists the organization's audit log, newest first: all of it, or only the entries with ?action=,
// ?target_id= or ?actor_id= (a user ID or an API key ID). Only owners and admins may read it.
func (s *Server) listAuditEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "forbidden"})
		return
	}
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	entries := s.store.AuditEvents(p.OrgID, store.AuditFilter{Action: q.Get("action"), TargetID: q.Get("target_id"), ActorID: q.Get("actor_id")})
	views := make([]auditView, 0, len(entries))
	for _, e := range entries {
		views = append(views, auditView{ID: e.ID, Action: e.Action, Actor: e.Actor, Target: e.Target, RequestID: e.RequestID, At: e.At, Changes: e.Changes})
	}
	items, next := pageOfNewest(views, auditViewKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

