package store

import (
	"fmt"
	"sort"
	"time"
)

// AuditEntry is one row of an organization's audit log: a change made by a successful API request. Entries are never
// changed or deleted.
type AuditEntry struct {
	ID        string      `json:"id"`
	OrgID     string      `json:"org_id"`
	Action    string      `json:"action"`
	Actor     AuditActor  `json:"actor"`
	Target    AuditTarget `json:"target"`
	RequestID string      `json:"request_id"`
	At        time.Time   `json:"at"`
	// Changes is set for updates: the fields whose value changed. It is a pointer so that an update which changed nothing
	// still carries it (empty), while the other entries do not.
	Changes *map[string]AuditChange `json:"changes,omitempty"`
}

// AuditActor is who made a change: an API key, and the member the key acts for.
type AuditActor struct {
	Type   string `json:"type"`
	ID     string `json:"id"`
	UserID string `json:"user_id"`
}

// AuditTarget is what a change was made to.
type AuditTarget struct {
	Type string `json:"type"`
	ID   string `json:"id"`
}

// AuditChange is one field's value before and after an update.
type AuditChange struct {
	From any `json:"from"`
	To   any `json:"to"`
}

// AuditFilter selects audit entries. Empty fields match everything. ActorID is a user ID or an API key ID.
type AuditFilter struct {
	Action   string
	TargetID string
	ActorID  string
}

// AppendAudit adds an entry to the audit log at now. The caller sets everything but ID and At.
func (s *Store) AppendAudit(e AuditEntry, now time.Time) AuditEntry {
	s.mu.Lock()
	defer s.mu.Unlock()
	e.ID = fmt.Sprintf("aud_%06d", len(s.audit)+1)
	e.At = now.UTC()
	s.audit = append(s.audit, e)
	return e
}

// AuditEvents returns an organization's audit entries that match f, newest first.
func (s *Store) AuditEvents(orgID string, f AuditFilter) []AuditEntry {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []AuditEntry{}
	for _, e := range s.audit {
		if e.OrgID != orgID || (f.Action != "" && e.Action != f.Action) || (f.TargetID != "" && e.Target.ID != f.TargetID) {
			continue
		}
		if f.ActorID != "" && e.Actor.ID != f.ActorID && e.Actor.UserID != f.ActorID {
			continue
		}
		out = append(out, e)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].At.Equal(out[j].At) {
			return out[i].At.After(out[j].At)
		}
		return out[i].ID > out[j].ID
	})
	return out
}
