package api_test

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// auditEntry is an entry of GET /v1/audit-events, as the API shows it.
type auditEntry struct {
	ID        string                         `json:"id"`
	Action    string                         `json:"action"`
	Actor     store.AuditActor               `json:"actor"`
	Target    store.AuditTarget              `json:"target"`
	RequestID string                         `json:"request_id"`
	At        time.Time                      `json:"at"`
	Changes   *map[string]store.AuditChange `json:"changes"`
}

// auditPage lists the Acme owner's audit entries for a query, newest first, with the next page's cursor.
func auditPage(t *testing.T, e *apitest.Env, query string) ([]auditEntry, string) {
	t.Helper()
	var out struct {
		Items      []auditEntry `json:"items"`
		NextCursor string       `json:"next_cursor"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, e.Acme.Key, nil, &out)
	return out.Items, out.NextCursor
}

// newestAudit is the Acme owner's most recent audit entry.
func newestAudit(t *testing.T, e *apitest.Env) auditEntry {
	t.Helper()
	items, _ := auditPage(t, e, "?limit=1")
	if len(items) != 1 {
		t.Fatalf("no audit entries")
	}
	return items[0]
}

// auditCount is how many entries the Acme organization's audit log holds.
func auditCount(e *apitest.Env) int {
	return len(e.Store.AuditEvents(e.Acme.ID, store.AuditFilter{}))
}

func TestAuditRecordsSuccessfulChanges(t *testing.T) {
	e := apitest.New(t)
	key, _ := e.Store.APIKeyByToken(e.Acme.Key)
	// last checks that the newest entry is action on target, made by the owner's key, and returns it.
	last := func(action, targetType, targetID string) auditEntry {
		t.Helper()
		got := newestAudit(t, e)
		if got.Action != action || got.Target != (store.AuditTarget{Type: targetType, ID: targetID}) {
			t.Fatalf("newest = %+v, want %s on %s %s", got, action, targetType, targetID)
		}
		if got.Actor != (store.AuditActor{Type: "api_key", ID: key.ID, UserID: e.Acme.Owner.ID}) {
			t.Fatalf("actor = %+v", got.Actor)
		}
		if got.At.IsZero() {
			t.Fatalf("no time in %+v", got)
		}
		return got
	}

	var c store.Customer
	r := e.DoWith("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane", "email": "jane@example.com"}, http.Header{"X-Request-Id": {"req-create"}})
	r.JSON(t, &c)
	if r.Code != http.StatusCreated {
		t.Fatalf("create customer: %s", r)
	}
	if got := last("customer.created", "customer", c.ID); got.Changes != nil || got.RequestID != "req-create" {
		t.Fatalf("create entry = %+v", got)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	got := last("customer.updated", "customer", c.ID)
	if got.Changes == nil || len(*got.Changes) != 1 || (*got.Changes)["name"].From != "Jane" || (*got.Changes)["name"].To != "Jane Roe" {
		t.Fatalf("changes = %+v", got.Changes)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	if got := last("customer.updated", "customer", c.ID); got.Changes == nil || len(*got.Changes) != 0 {
		t.Fatalf("an update that changed nothing: changes = %+v", got.Changes)
	}

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+c.ID, e.Acme.Key, nil, nil)
	last("customer.deleted", "customer", c.ID)

	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	last("plan.created", "plan", p.ID)
	e.MustDo(http.StatusOK, "PATCH", "/v1/plans/"+p.ID, e.Acme.Key, map[string]string{"name": "Team Plus"}, nil)
	if got := last("plan.updated", "plan", p.ID); got.Changes == nil || (*got.Changes)["name"].To != "Team Plus" || len(*got.Changes) != 1 {
		t.Fatalf("plan changes = %+v", got.Changes)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]string{"name": "Acme Ltd"}, nil)
	if got := last("org.updated", "org", e.Acme.ID); got.Changes == nil || (*got.Changes)["name"].From != "Acme" || (*got.Changes)["name"].To != "Acme Ltd" {
		t.Fatalf("org changes = %+v", got.Changes)
	}
}

func TestAuditSubscriptionsAndInvoices(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "quantity": 2}, &sub)
	if got := newestAudit(t, e); got.Action != "subscription.created" || got.Target.ID != sub.ID {
		t.Fatalf("newest = %+v", got)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]int{"quantity": 3}, nil)
	got := newestAudit(t, e)
	if got.Action != "subscription.updated" || got.Changes == nil || (*got.Changes)["quantity"].From != float64(2) || (*got.Changes)["quantity"].To != float64(3) {
		t.Fatalf("subscription update = %+v", got)
	}
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", e.Acme.Key, map[string]bool{"at_period_end": true}, nil)
	if got := newestAudit(t, e); got.Action != "subscription.canceled" || got.Target.ID != sub.ID || got.Changes != nil {
		t.Fatalf("cancel = %+v", got)
	}

	newInvoice := func() store.Invoice {
		var inv store.Invoice
		e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": c.ID, "currency": "USD",
			"lines": []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 1000}}}, &inv)
		return inv
	}
	paid, declined, voided := newInvoice(), newInvoice(), newInvoice()
	if got := newestAudit(t, e); got.Action != "invoice.created" || got.Target.ID != voided.ID {
		t.Fatalf("invoice create = %+v", got)
	}

	if r := e.Do("POST", "/v1/invoices/"+declined.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_declined"}); r.Code != http.StatusPaymentRequired {
		t.Fatalf("declined: %s", r)
	}
	before := auditCount(e)
	if got := newestAudit(t, e); got.Action == "invoice.paid" {
		t.Fatalf("a declined payment was recorded: %+v", got)
	}

	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+paid.ID+"/pay", e.Acme.Key, map[string]string{"payment_method": "pm_card_visa"}, nil)
	if got := newestAudit(t, e); got.Action != "invoice.paid" || got.Target != (store.AuditTarget{Type: "invoice", ID: paid.ID}) {
		t.Fatalf("pay = %+v", got)
	}
	if n := auditCount(e); n != before+1 {
		t.Fatalf("paying added %d entries", n-before)
	}

	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+voided.ID+"/void", e.Acme.Key, nil, nil)
	if got := newestAudit(t, e); got.Action != "invoice.voided" || got.Target.ID != voided.ID {
		t.Fatalf("void = %+v", got)
	}
}

func TestAuditTeamAndKeys(t *testing.T) {
	e := apitest.New(t)
	user, _ := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+user.ID, e.Acme.Key, map[string]string{"role": "member"}, nil)
	got := newestAudit(t, e)
	if got.Action != "member.role_changed" || got.Target != (store.AuditTarget{Type: "member", ID: user.ID}) ||
		got.Changes == nil || len(*got.Changes) != 1 || (*got.Changes)["role"].From != "viewer" || (*got.Changes)["role"].To != "member" {
		t.Fatalf("role change = %+v", got)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+user.ID, e.Acme.Key, nil, nil)
	if got := newestAudit(t, e); got.Action != "member.removed" || got.Target != (store.AuditTarget{Type: "member", ID: user.ID}) {
		t.Fatalf("removed = %+v", got)
	}

	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@people.example", "role": "member"}, &inv)
	if got := newestAudit(t, e); got.Action != "invite.created" || got.Target != (store.AuditTarget{Type: "invite", ID: inv.ID}) {
		t.Fatalf("invite = %+v", got)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+inv.ID, e.Acme.Key, nil, nil)
	if got := newestAudit(t, e); got.Action != "invite.revoked" || got.Target.ID != inv.ID {
		t.Fatalf("revoked = %+v", got)
	}

	var k store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &k)
	if got := newestAudit(t, e); got.Action != "api_key.created" || got.Target != (store.AuditTarget{Type: "api_key", ID: k.ID}) {
		t.Fatalf("key = %+v", got)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+k.ID, e.Acme.Key, nil, nil)
	if got := newestAudit(t, e); got.Action != "api_key.revoked" || got.Target.ID != k.ID {
		t.Fatalf("key revoked = %+v", got)
	}
}

func TestAuditWebhookEndpoints(t *testing.T) {
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	if got := newestAudit(t, e); got.Action != "webhook_endpoint.created" || got.Target.ID != ep.ID {
		t.Fatalf("created = %+v", got)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]string{"url": "https://hooks.acme.example/v2"}, nil)
	got := newestAudit(t, e)
	if got.Action != "webhook_endpoint.updated" || got.Changes == nil || len(*got.Changes) != 1 || (*got.Changes)["url"].To != "https://hooks.acme.example/v2" {
		t.Fatalf("updated = %+v", got)
	}
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil, nil)
	if got := newestAudit(t, e); got.Action != "webhook_endpoint.deleted" || got.Target.ID != ep.ID {
		t.Fatalf("deleted = %+v", got)
	}
}

func TestAuditRecordsOnlySuccesses(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	before := auditCount(e)

	for _, r := range []*apitest.Response{
		e.Do("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "JANE@example.com"}), // 409
		e.Do("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "", "email": "x@example.com"}),          // 422
		e.Do("PATCH", "/v1/customers/cus_missing", e.Acme.Key, map[string]string{"name": "X"}),                     // 404
		e.Do("GET", "/v1/customers", e.Acme.Key, nil),                                                             // read
		e.Do("POST", "/v1/customers", viewer, map[string]string{"name": "X", "email": "x@example.com"}),            // 403
	} {
		if r.Code < 300 {
			t.Fatalf("expected a failure or a read: %s", r)
		}
	}
	if n := auditCount(e); n != before {
		t.Fatalf("failed requests recorded %d entries", n-before)
	}
}

func TestAuditNeverHoldsSecrets(t *testing.T) {
	e := apitest.New(t)
	var k store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", e.Acme.Key, map[string]string{"name": "CI"}, &k)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, map[string]string{"url": "https://hooks.acme.example/v2"}, nil)
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", e.Acme.Key, map[string]string{"email": "new@people.example", "role": "member"}, &inv)

	if k.Token == "" || ep.Secret == "" || inv.Token == "" {
		t.Fatalf("no secrets to check: %+v %+v %+v", k, ep, inv)
	}
	r := e.Do("GET", "/v1/audit-events", e.Acme.Key, nil)
	body := string(r.Body)
	for _, secret := range []string{k.Token, ep.Secret, inv.Token} {
		if strings.Contains(body, secret) {
			t.Fatalf("the audit log holds a secret: %s", body)
		}
	}
	if !strings.Contains(body, `"action":"webhook_endpoint.updated"`) {
		t.Fatalf("no endpoint update in %s", body)
	}
}

func TestAuditFiltersAndPaging(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Ann", "ann@example.com")
	ben := e.CreateCustomer(e.Acme, "Ben", "ben@example.com")
	cy := e.CreateCustomer(e.Acme, "Cy", "cy@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	e.MustDo(http.StatusOK, "PATCH", "/v1/plans/"+p.ID, e.Acme.Key, map[string]string{"name": "Team Plus"}, nil)

	byAction, _ := auditPage(t, e, "?action=customer.created")
	if len(byAction) != 3 {
		t.Fatalf("customer.created: %d entries", len(byAction))
	}
	byTarget, _ := auditPage(t, e, "?target_id="+ben.ID)
	if len(byTarget) != 1 || byTarget[0].Action != "customer.created" {
		t.Fatalf("target_id: %+v", byTarget)
	}

	first, next := auditPage(t, e, "?action=customer.created&limit=2")
	if len(first) != 2 || next == "" || first[0].Target.ID != cy.ID || first[1].Target.ID != ben.ID {
		t.Fatalf("first page = %+v, next %q", first, next)
	}
	second, next := auditPage(t, e, "?action=customer.created&limit=2&cursor="+next)
	if len(second) != 1 || next != "" || second[0].Target.ID == cy.ID || second[0].Target.ID == ben.ID {
		t.Fatalf("second page = %+v, next %q", second, next)
	}

	if all, _ := auditPage(t, e, ""); len(all) < 5 || all[0].Action != "plan.updated" {
		t.Fatalf("all entries = %+v", all)
	}
}

func TestAuditIsForOwnersAndAdmins(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	for _, role := range []store.Role{store.RoleBilling, store.RoleMember, store.RoleViewer} {
		_, key := e.AddMember(e.Acme, string(role)+"@acme.example", role)
		if r := e.Do("GET", "/v1/audit-events", key, nil); r.Code != http.StatusForbidden {
			t.Fatalf("%s: %s", role, r)
		}
	}
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	if r := e.Do("GET", "/v1/audit-events", admin, nil); r.Code != http.StatusOK {
		t.Fatalf("admin: %s", r)
	}
	if r := e.Do("GET", "/v1/audit-events", e.Globex.Key, nil); r.Code != http.StatusOK || strings.Contains(string(r.Body), `"items":[{`) {
		t.Fatalf("another organization's log: %s", r)
	}
}

