package api_test

import (
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// auditEntry is an entry of GET /v1/audit-events, as the API shows it.
type auditEntry struct {
	ID        string                         `json:"id"`
	Action    string                         `json:"action"`
	Actor     store.AuditActor               `json:"actor"`
	Target    store.AuditTarget              `json:"target"`
	RequestID string                         `json:"request_id"`
	At        time.Time                      `json:"at"`
	Changes   *map[string]store.AuditChange `json:"changes"`
}

// auditPage lists the Acme owner's audit entries for a query, newest first, with the next page's cursor.
func auditPage(t *testing.T, e *apitest.Env, query string) ([]auditEntry, string) {
	t.Helper()
	var out struct {
		Items      []auditEntry `json:"items"`
		NextCursor string       `json:"next_cursor"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, e.Acme.Key, nil, &out)
	return out.Items, out.NextCursor
}

// newestAudit is the Acme owner's most recent audit entry.
func newestAudit(t *testing.T, e *apitest.Env) auditEntry {
	t.Helper()
	items, _ := auditPage(t, e, "?limit=1")
	if len(items) != 1 {
		t.Fatalf("no audit entries")
	}
	return items[0]
}

// auditCount is how many entries the Acme organization's audit log holds.
func auditCount(e *apitest.Env) int {
	return len(e.Store.AuditEvents(e.Acme.ID, store.AuditFilter{}))
}

func TestAuditRecordsSuccessfulChanges(t *testing.T) {
	e := apitest.New(t)
	key, _ := e.Store.APIKeyByToken(e.Acme.Key)
	// last checks that the newest entry is action on target, made by the owner's key, and returns it.
	last := func(action, targetType, targetID string) auditEntry {
		t.Helper()
		got := newestAudit(t, e)
		if got.Action != action || got.Target != (store.AuditTarget{Type: targetType, ID: targetID}) {
			t.Fatalf("newest = %+v, want %s on %s %s", got, action, targetType, targetID)
		}
		if got.Actor != (store.AuditActor{Type: "api_key", ID: key.ID, UserID: e.Acme.Owner.ID}) {
			t.Fatalf("actor = %+v", got.Actor)
		}
		if got.At.IsZero() {
			t.Fatalf("no time in %+v", got)
		}
		return got
	}

	var c store.Customer
	r := e.DoWith("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane", "email": "jane@example.com"}, http.Header{"X-Request-Id": {"req-create"}})
	r.JSON(t, &c)
	if r.Code != http.StatusCreated {
		t.Fatalf("create customer: %s", r)
	}
	if got := last("customer.created", "customer", c.ID); got.Changes != nil || got.RequestID != "req-create" {
		t.Fatalf("create entry = %+v", got)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	got := last("customer.updated", "customer", c.ID)
	if got.Changes == nil || len(*got.Changes) != 1 || (*got.Changes)["name"].From != "Jane" || (*got.Changes)["name"].To != "Jane Roe" {
		t.Fatalf("changes = %+v", got.Changes)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, e.Acme.Key, map[string]string{"name": "Jane Roe"}, nil)
	if got := last("customer.updated", "customer", c.ID); got.Changes == nil || len(*got.Changes) != 0 {
		t.Fatalf("an update that changed nothing: changes = %+v", got.Changes)
	}

	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+c.ID, e.Acme.Key, nil, nil)
	last("customer.deleted", "customer", c.ID)

	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	last("plan.created", "plan", p.ID)
	e.MustDo(http.StatusOK, "PATCH", "/v1/plans/"+p.ID, e.Acme.Key, map[string]string{"name": "Team Plus"}, nil)
	if got := last("plan.updated", "plan", p.ID); got.Changes == nil || (*got.Changes)["name"].To != "Team Plus" || len(*got.Changes) != 1 {
		t.Fatalf("plan changes = %+v", got.Changes)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]string{"name": "Acme Ltd"}, nil)
	if got := last("org.updated", "org", e.Acme.ID); got.Changes == nil || (*got.Changes)["name"].From != "Acme" || (*got.Changes)["name"].To != "Acme Ltd" {
		t.Fatalf("org changes = %+v", got.Changes)
	}
}

